cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void convT3d_kernel(
    const T* __restrict__ X, const T* __restrict__ W, const T* __restrict__ Bp,
    T* __restrict__ Y,
    int N, int Cin, int Din, int Hin, int Win,
    int Cout, int Dout, int Hout, int Wout,
    int K, int stride, int padding, int output_padding,
    int groups, int Cin_per_group, int Cout_per_group)
{
    extern __shared__ float smem_raw[];

    constexpr int Threads    = 128;
    constexpr int PVec       = 2;
    constexpr int OcPerBlock = 8;

    const int tid = threadIdx.x;

    const int n       = blockIdx.z;
    const int c_tile  = blockIdx.y;
    const int c_base  = c_tile * OcPerBlock;

    const int P_total = Dout * Hout * Wout;
    const int PTile   = Threads * PVec;
    const int p_block = blockIdx.x * PTile;

    const int64_t sXn = (int64_t)Cin * Din * Hin * Win;
    const int64_t sXc = (int64_t)Din * Hin * Win;
    const int64_t sXd = (int64_t)Hin * Win;
    const int64_t sXh = (int64_t)Win;

    const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
    const int64_t sYc = (int64_t)Dout * Hout * Wout;
    const int64_t sYd = (int64_t)Hout * Wout;
    const int64_t sYh = (int64_t)Wout;

    auto mX = make_tensor(
        make_gmem_ptr(X + (int64_t)n * sXn),
        make_shape(Cin, Din, Hin, Win),
        make_stride(sXc, sXd, sXh, Int<1>{}));

    auto mY = make_tensor(
        make_gmem_ptr(Y + (int64_t)n * sYn),
        make_shape(Cout, Dout, Hout, Wout),
        make_stride(sYc, sYd, sYh, Int<1>{}));

    const int KKK = K * K * K;
    auto mW = make_tensor(
        make_gmem_ptr(W),
        make_shape(Cin, Cout_per_group, K, K, K),
        make_stride((int64_t)Cout_per_group * KKK, (int64_t)KKK, (int64_t)K * K, (int64_t)K, Int<1>{}));

    auto sW = make_tensor(
        make_smem_ptr(smem_raw),
        make_shape(OcPerBlock, Cin_per_group, K, K, K),
        make_stride((int64_t)Cin_per_group * KKK, (int64_t)KKK, (int64_t)K * K, (int64_t)K, Int<1>{}));

    const int total_w = OcPerBlock * Cin_per_group * KKK;
    for (int idx = tid; idx < total_w; idx += Threads) {
        int rem = idx;
        int kw = rem % K; rem /= K;
        int kh = rem % K; rem /= K;
        int kd = rem % K; rem /= K;
        int icl = rem % Cin_per_group; rem /= Cin_per_group;
        int occ = rem;

        int oc = c_base + occ;
        T val = T(0);
        if (oc < Cout) {
            int group = oc / Cout_per_group;
            int oc_local = oc % Cout_per_group;
            int ic_full = group * Cin_per_group + icl;
            val = mW(ic_full, oc_local, kd, kh, kw);
        }
        sW(occ, icl, kd, kh, kw) = val;
    }
    __syncthreads();

    int  p_idx[PVec];
    int  od_arr[PVec], oh_arr[PVec], ow_arr[PVec];
    bool valid_p[PVec];

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
        int p = p_block + tid + i * Threads;
        p_idx[i] = p;
        if (p < P_total) {
            int od = p / (Hout * Wout);
            int rem = p - od * (Hout * Wout);
            int oh = rem / Wout;
            int ow = rem - oh * Wout;
            od_arr[i] = od; oh_arr[i] = oh; ow_arr[i] = ow;
            valid_p[i] = true;
        } else {
            od_arr[i] = 0; oh_arr[i] = 0; ow_arr[i] = 0;
            valid_p[i] = false;
        }
    }

    float acc[OcPerBlock][PVec];
    #pragma unroll
    for (int occ = 0; occ < OcPerBlock; ++occ) {
        int oc = c_base + occ;
        float bval = 0.0f;
        if (Bp != nullptr && oc < Cout) bval = (float)Bp[oc];
        #pragma unroll
        for (int i = 0; i < PVec; ++i) acc[occ][i] = bval;
    }

    for (int kd = 0; kd < K; ++kd) {
    for (int kh = 0; kh < K; ++kh) {
    for (int kw = 0; kw < K; ++kw) {

        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
            if (!valid_p[i]) continue;
            int od = od_arr[i], oh = oh_arr[i], ow = ow_arr[i];

            int id_ = od + padding - kd;
            if (id_ < 0 || (id_ % stride) != 0) continue;
            int id = id_ / stride;
            if (id >= Din) continue;

            int ih_ = oh + padding - kh;
            if (ih_ < 0 || (ih_ % stride) != 0) continue;
            int ih = ih_ / stride;
            if (ih >= Hin) continue;

            int iw_ = ow + padding - kw;
            if (iw_ < 0 || (iw_ % stride) != 0) continue;
            int iw = iw_ / stride;
            if (iw >= Win) continue;

            for (int icl = 0; icl < Cin_per_group; ++icl) {
                int group_prev = -1;
                float xval_cache = 0.0f;
                #pragma unroll
                for (int occ = 0; occ < OcPerBlock; ++occ) {
                    int oc = c_base + occ;
                    if (oc >= Cout) continue;
                    int group = oc / Cout_per_group;
                    int ic_full = group * Cin_per_group + icl;
                    float xval;
                    if (group == group_prev) {
                        xval = xval_cache;
                    } else {
                        xval = (float)mX(ic_full, id, ih, iw);
                        xval_cache = xval;
                        group_prev = group;
                    }
                    float wval = (float)sW(occ, icl, kd, kh, kw);
                    acc[occ][i] += xval * wval;
                }
            }
        }
    }}}

    #pragma unroll
    for (int occ = 0; occ < OcPerBlock; ++occ) {
        int oc = c_base + occ;
        if (oc >= Cout) continue;
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
            if (!valid_p[i]) continue;
            mY(oc, od_arr[i], oh_arr[i], ow_arr[i]) = static_cast<T>(acc[occ][i]);
        }
    }
}

torch::Tensor convtranspose3d_forward(torch::Tensor x,
                                       torch::Tensor weight,
                                       c10::optional<torch::Tensor> bias,
                                       int stride, int padding, int output_padding, int groups) {
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat, "float32 only");
    TORCH_CHECK(x.dim() == 5, "x must be [N, C, D, H, W]");
    TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout/groups, K, K, K]");
    if (bias.has_value()) TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    int64_t N   = x_c.size(0);
    int64_t Cin = x_c.size(1);
    int64_t Din = x_c.size(2);
    int64_t Hin = x_c.size(3);
    int64_t Win = x_c.size(4);

    int64_t Cout_per_group = w_c.size(1);
    int64_t K = w_c.size(2);
    TORCH_CHECK(w_c.size(3) == K && w_c.size(4) == K, "kernel must be cubic");
    TORCH_CHECK(w_c.size(0) == Cin, "weight in_channels mismatch");

    int64_t Cout = Cout_per_group * groups;
    int64_t Cin_per_group = Cin / groups;
    TORCH_CHECK(Cin_per_group * groups == Cin, "Cin must be divisible by groups");

    int64_t Dout = (Din - 1) * stride - 2 * padding + K + output_padding;
    int64_t Hout = (Hin - 1) * stride - 2 * padding + K + output_padding;
    int64_t Wout = (Win - 1) * stride - 2 * padding + K + output_padding;
    TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid output shape");

    auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

    torch::Tensor b_c;
    const float* bias_ptr = nullptr;
    if (bias.has_value()) {
        b_c = bias.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias shape mismatch");
        bias_ptr = b_c.data_ptr<float>();
    }

    constexpr int Threads = 128;
    constexpr int PVec = 2;
    constexpr int OcPerBlock = 8;

    int64_t P_total = Dout * Hout * Wout;
    int64_t PTile = (int64_t)Threads * PVec;

    dim3 block(Threads);
    dim3 grid(
        (unsigned)((P_total + PTile - 1) / PTile),
        (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
        (unsigned)N
    );

    size_t shared_bytes = (size_t)OcPerBlock * (size_t)Cin_per_group * (size_t)(K * K * K) * sizeof(float);

    if (shared_bytes > 48 * 1024) {
        cudaFuncSetAttribute(convT3d_kernel<float>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shared_bytes);
    }

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    convT3d_kernel<float><<<grid, block, shared_bytes, stream>>>(
        x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr,
        y.data_ptr<float>(),
        (int)N, (int)Cin, (int)Din, (int)Hin, (int)Win,
        (int)Cout, (int)Dout, (int)Hout, (int)Wout,
        (int)K, (int)stride, (int)padding, (int)output_padding,
        (int)groups, (int)Cin_per_group, (int)Cout_per_group
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "convT3d_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

convT3d_ext = load_inline(
    name="cute_convtranspose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["convtranspose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution (square kernel) implemented with a custom
    CUTE/CUDA kernel. Parameters (weight/bias) are held by a standard
    nn.ConvTranspose3d module (for correct default initialization), but the
    actual forward computation is performed entirely by the custom kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias
        )
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self._ext = convT3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv_transpose3d.weight
        bias = self.conv_transpose3d.bias
        return self._ext.convtranspose3d_forward(
            x.contiguous(),
            weight.contiguous(),
            bias.contiguous() if bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.output_padding),
            int(self.groups),
        )

